PRAGMA foreign_keys=ON;
CREATE TABLE dim_area(area_id INTEGER PRIMARY KEY,nome TEXT NOT NULL UNIQUE);
CREATE TABLE dim_usuario(usuario_id INTEGER PRIMARY KEY,nome TEXT NOT NULL,area_id INTEGER NOT NULL,cargo TEXT NOT NULL,mfa_ativo INTEGER NOT NULL,risco_usuario TEXT NOT NULL,FOREIGN KEY(area_id) REFERENCES dim_area(area_id));
CREATE TABLE dim_ativo(ativo_id INTEGER PRIMARY KEY,codigo TEXT NOT NULL UNIQUE,tipo TEXT NOT NULL,area_id INTEGER NOT NULL,sistema_operacional TEXT NOT NULL,criticidade TEXT NOT NULL,status TEXT NOT NULL,data_aquisicao TEXT NOT NULL,FOREIGN KEY(area_id) REFERENCES dim_area(area_id));
CREATE TABLE fato_vulnerabilidade(vulnerabilidade_id INTEGER PRIMARY KEY,ativo_id INTEGER NOT NULL,cve TEXT NOT NULL,descricao TEXT NOT NULL,severidade TEXT NOT NULL,cvss INTEGER NOT NULL,data_deteccao TEXT NOT NULL,data_correcao TEXT,status TEXT NOT NULL,sla_dias INTEGER NOT NULL,FOREIGN KEY(ativo_id) REFERENCES dim_ativo(ativo_id));
CREATE TABLE fato_alerta(alerta_id INTEGER PRIMARY KEY,ativo_id INTEGER NOT NULL,data_hora TEXT NOT NULL,fonte TEXT NOT NULL,tipo_ataque TEXT NOT NULL,severidade TEXT NOT NULL,pais_origem TEXT NOT NULL,falso_positivo INTEGER NOT NULL,status TEXT NOT NULL,FOREIGN KEY(ativo_id) REFERENCES dim_ativo(ativo_id));
CREATE TABLE fato_incidente(incidente_id INTEGER PRIMARY KEY,alerta_id INTEGER NOT NULL,ativo_id INTEGER NOT NULL,tipo_ataque TEXT NOT NULL,severidade TEXT NOT NULL,inicio TEXT NOT NULL,fim TEXT,mttd_min INTEGER NOT NULL,mttr_contencao_min INTEGER NOT NULL,status TEXT NOT NULL,registros_comprometidos INTEGER NOT NULL,notificacao_lgpd INTEGER NOT NULL,perda_estimada REAL NOT NULL,FOREIGN KEY(alerta_id) REFERENCES fato_alerta(alerta_id),FOREIGN KEY(ativo_id) REFERENCES dim_ativo(ativo_id));
CREATE TABLE fato_resposta(resposta_id INTEGER PRIMARY KEY,incidente_id INTEGER NOT NULL,etapa TEXT NOT NULL,data_hora TEXT NOT NULL,equipe TEXT NOT NULL,status TEXT NOT NULL,duracao_min INTEGER NOT NULL,FOREIGN KEY(incidente_id) REFERENCES fato_incidente(incidente_id));
CREATE TABLE fato_custo_incidente(custo_id INTEGER PRIMARY KEY,incidente_id INTEGER NOT NULL,parada_operacional REAL NOT NULL,recuperacao REAL NOT NULL,consultoria REAL NOT NULL,juridico REAL NOT NULL,comunicacao REAL NOT NULL,FOREIGN KEY(incidente_id) REFERENCES fato_incidente(incidente_id));
CREATE TABLE fato_tentativa_login(tentativa_id INTEGER PRIMARY KEY,usuario_id INTEGER NOT NULL,data_hora TEXT NOT NULL,pais_origem TEXT NOT NULL,sistema TEXT NOT NULL,sucesso INTEGER NOT NULL,login_suspeito INTEGER NOT NULL,FOREIGN KEY(usuario_id) REFERENCES dim_usuario(usuario_id));
CREATE TABLE fato_phishing(phishing_id INTEGER PRIMARY KEY,usuario_id INTEGER NOT NULL,data_envio TEXT NOT NULL,tipo TEXT NOT NULL,isca TEXT NOT NULL,clicou INTEGER NOT NULL,informou_credencial INTEGER NOT NULL,reportou INTEGER NOT NULL,FOREIGN KEY(usuario_id) REFERENCES dim_usuario(usuario_id));
CREATE TABLE fato_treinamento(treinamento_id INTEGER PRIMARY KEY,usuario_id INTEGER NOT NULL,tema TEXT NOT NULL,data_limite TEXT NOT NULL,status TEXT NOT NULL,nota INTEGER,FOREIGN KEY(usuario_id) REFERENCES dim_usuario(usuario_id));
CREATE INDEX idx_alerta_data ON fato_alerta(data_hora); CREATE INDEX idx_incidente_inicio ON fato_incidente(inicio); CREATE INDEX idx_vuln_status ON fato_vulnerabilidade(status); CREATE INDEX idx_login_usuario ON fato_tentativa_login(usuario_id);
